import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ActivatedRoute } from '@angular/router';
import { RsvpService, Guest, RsvpResponse } from '../../services/rsvp.service';

@Component({
  selector: 'app-rsvp-form',
  standalone: true,
  imports: [CommonModule, FormsModule],
  template: `
    <section class="rsvp" id="rsvp">
      <div class="container">
        <h2>Daj znać, że będziesz z nami!</h2>

        <div *ngIf="loading" class="loading">
          Ładowanie...
        </div>

        <div *ngIf="error" class="error">
          {{ error }}
        </div>

        <div *ngIf="!loading && !error && guests.length > 0" class="form-container">
          <form (ngSubmit)="onSubmit()" #rsvpForm="ngForm">

            <div *ngFor="let guest of guests; let i = index" class="guest-card">
              <h3>
                {{ guest.firstName }} {{ guest.lastName }}
                <span *ngIf="guest.isChild" class="child-badge">(dziecko)</span>
              </h3>

              <div class="form-group">
                <label>Czy będziesz obecny/a?</label>
                <div class="radio-group">
                  <label class="radio-label">
                    <input 
                      type="radio" 
                      [name]="'attending-' + guest.id" 
                      [value]="true"
                      [(ngModel)]="guestResponses[i].isAttending"
                      required>
                    <span>Będę</span>
                  </label>
                  <label class="radio-label">
                    <input 
                      type="radio" 
                      [name]="'attending-' + guest.id" 
                      [value]="false"
                      [(ngModel)]="guestResponses[i].isAttending"
                      required>
                    <span>Nie będę</span>
                  </label>
                </div>
              </div>

              <div class="form-group">
                <label [for]="'allergies-' + guest.id">Alergie pokarmowe</label>
                <textarea 
                  [id]="'allergies-' + guest.id"
                  [name]="'allergies-' + guest.id"
                  [(ngModel)]="guestResponses[i].allergies"
                  placeholder="Proszę wpisać alergie (jeśli nie masz, zostaw puste)"
                  rows="3">
                </textarea>
              </div>
            </div>

            <div *ngIf="submitError" class="error">
              {{ submitError }}
            </div>

            <div *ngIf="submitSuccess" class="success">
              Dziękujemy! Twoja odpowiedź została zapisana.
            </div>

            <button 
              type="submit" 
              class="submit-btn"
              [disabled]="!rsvpForm.valid || submitting">
              {{ submitting ? 'Wysyłanie...' : 'Potwierdź obecność' }}
            </button>
          </form>
        </div>

        <div *ngIf="!loading && !error && guests.length === 0" class="no-invitation">
          Nie znaleziono zaproszenia. Sprawdź czy link jest poprawny.
        </div>
      </div>
    </section>
  `,
  styles: [`
    .rsvp {
      padding: 5rem 0;
      background: white;
    }

    .container {
      max-width: 800px;
      margin: 0 auto;
      padding: 0 2rem;
    }

    h2 {
      font-family: 'Playfair Display', serif;
      font-size: 3rem;
      text-align: center;
      margin-bottom: 3rem;
      color: #333;
    }

    .loading, .error, .no-invitation {
      text-align: center;
      padding: 2rem;
      font-family: 'Lato', sans-serif;
    }

    .error {
      color: #d32f2f;
      background: #ffebee;
      border-radius: 8px;
      margin-bottom: 1rem;
    }

    .success {
      color: #388e3c;
      background: #e8f5e9;
      border-radius: 8px;
      padding: 1rem;
      margin: 1rem 0;
      text-align: center;
    }

    .guest-card {
      background: #f8f6f4;
      padding: 2rem;
      border-radius: 8px;
      margin-bottom: 2rem;
      border: 2px solid #c9a961;
    }

    .guest-card h3 {
      font-family: 'Playfair Display', serif;
      font-size: 1.5rem;
      margin-bottom: 1.5rem;
      color: #333;
    }

    .child-badge {
      font-size: 0.9rem;
      color: #c9a961;
      font-style: italic;
    }

    .form-group {
      margin-bottom: 1.5rem;
    }

    label {
      display: block;
      font-family: 'Lato', sans-serif;
      font-weight: 600;
      margin-bottom: 0.5rem;
      color: #555;
    }

    .radio-group {
      display: flex;
      gap: 2rem;
    }

    .radio-label {
      display: flex;
      align-items: center;
      cursor: pointer;
      font-weight: normal;
    }

    .radio-label input[type="radio"] {
      margin-right: 0.5rem;
      width: 20px;
      height: 20px;
      cursor: pointer;
    }

    textarea {
      width: 100%;
      padding: 0.75rem;
      font-family: 'Lato', sans-serif;
      font-size: 1rem;
      border: 1px solid #ddd;
      border-radius: 4px;
      resize: vertical;
    }

    textarea:focus {
      outline: none;
      border-color: #c9a961;
    }

    .submit-btn {
      width: 100%;
      padding: 1rem 2rem;
      background: #c9a961;
      color: white;
      border: none;
      border-radius: 4px;
      font-family: 'Lato', sans-serif;
      font-size: 1.1rem;
      font-weight: 600;
      cursor: pointer;
      transition: background 0.3s;
    }

    .submit-btn:hover:not(:disabled) {
      background: #b89850;
    }

    .submit-btn:disabled {
      background: #ccc;
      cursor: not-allowed;
    }

    @media (max-width: 768px) {
      h2 {
        font-size: 2rem;
      }
      .guest-card {
        padding: 1.5rem;
      }
      .radio-group {
        flex-direction: column;
        gap: 1rem;
      }
    }
  `]
})
export class RsvpFormComponent implements OnInit {
  token: string = '';
  guests: Guest[] = [];
  guestResponses: RsvpResponse[] = [];

  loading: boolean = true;
  error: string = '';
  submitting: boolean = false;
  submitError: string = '';
  submitSuccess: boolean = false;

  constructor(
    private route: ActivatedRoute,
    private rsvpService: RsvpService
  ) {}

  ngOnInit() {
    this.route.paramMap.subscribe(params => {
      this.token = params.get('token') || '';
      if (this.token) {
        this.loadInvitation();
      } else {
        this.loading = false;
        this.error = 'Brak tokenu zaproszenia';
      }
    });
  }

  loadInvitation() {
    this.loading = true;
    this.error = '';

    this.rsvpService.getInvitation(this.token).subscribe({
      next: (invitation) => {
        this.guests = invitation.guests;

        // Inicjalizuj responses dla każdego gościa
        this.guestResponses = this.guests.map(guest => ({
          guestId: guest.id,
          isAttending: guest.isAttending !== undefined ? guest.isAttending : null as any,
          allergies: guest.allergies || ''
        }));

        this.loading = false;
      },
      error: (err) => {
        this.loading = false;
        this.error = 'Nie udało się załadować zaproszenia. Sprawdź czy link jest poprawny.';
        console.error('Error loading invitation:', err);
      }
    });
  }

  onSubmit() {
    // Walidacja - sprawdź czy wszystkie pola isAttending są wypełnione
    const allFilled = this.guestResponses.every(r => r.isAttending !== null);

    if (!allFilled) {
      this.submitError = 'Proszę wypełnić wszystkie wymagane pola';
      return;
    }

    this.submitting = true;
    this.submitError = '';
    this.submitSuccess = false;

    this.rsvpService.submitRsvp(this.token, this.guestResponses).subscribe({
      next: (response) => {
        this.submitting = false;
        this.submitSuccess = true;
        this.submitError = '';

        // Scroll to success message
        setTimeout(() => {
          window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
        }, 100);
      },
      error: (err) => {
        this.submitting = false;
        this.submitError = 'Nie udało się zapisać odpowiedzi. Spróbuj ponownie.';
        console.error('Error submitting RSVP:', err);
      }
    });
  }
}
